import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BTLSZHNB.js";const p=JSON.parse('{"title":"ObjectBucket — takoform_edge_object_bucket","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/object-bucket.md","filePath":"proposals/edge/object-bucket.md"}'),i={name:"proposals/edge/object-bucket.md"};function d(c,e,s,n,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="objectbucket-—-takoform-edge-object-bucket" tabindex="-1">ObjectBucket — <code>takoform_edge_object_bucket</code> <a class="header-anchor" href="#objectbucket-—-takoform-edge-object-bucket" aria-label="Permalink to &quot;ObjectBucket — `takoform_edge_object_bucket`&quot;">​</a></h1><p>The shipped resource type is the transitional name <code>takoform_edge_object_bucket</code>: the retained provider-v2 lane still owns <code>takoform_object_bucket</code> while both lanes are co-registered in one provider binary. A future provider major that drops the retained v2 lane reclaims <code>takoform_object_bucket</code> for this Form.</p><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A worker stores and serves larger immutable-ish payloads — uploads, media, exports — in a flat-namespace object store. Workers consume it through <code>module-worker.object-bucket</code> bindings.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>. The bucket has no desired fields; its semantics are entirely fixed by the <code>edge.objects</code> Interface. There is no versioning field: object versioning changes observable read semantics and would be a different Form.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>edge.objects@1.0.0</code> contract: head/get/put/delete/list plus the four multipart operations, strong read-after-write consistency (a get, head, or list after a resolved put or delete observes it), last-writer-wins per key, strong etags with conditional reads and writes (<code>precondition_failed</code> on mismatch), and cursor pagination with delimiter roll-up.</p><p>Bodies STREAM. <code>get</code> and <code>put</code> declare <code>bodyStream</code> and <code>contentLength</code>, and the bytes travel beside the operation document rather than inside it, which is what makes the 5 GiB object ceiling meaningful at all. Ranged and conditional reads are typed inputs of <code>get</code> — not prose — and objects above <code>maxSinglePutBytes</code>, or of unknown size, are written through <code>createMultipartUpload</code> / <code>uploadPart</code> / <code>completeMultipartUpload</code> / <code>abortMultipartUpload</code> (decision 0020).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Consumers rely on read-after-write visibility and etag fencing as one inseparable model; the storage identity and that model must not drift apart.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Operating rules — CORS, lifecycle expiry, retention lock — are separate policy resources in the family plan. An eventually consistent object store or a versioned bucket is a different Form.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>edge.objects@1.0.0</code>.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; it is a binding target (<code>module-worker.object-bucket</code>).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a bucket bound by any Worker Version must fail with <code>dependency_in_use</code>. Delete destroys all objects. S3-compatible external access is adapter material, never a desired field (<a href="./../../spec/portability-boundary.html">spec/portability-boundary.md</a>).</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The strongly consistent object storage of a proven edge platform. The retained v1alpha2 <code>ObjectBucket</code> candidate is prior art; its <code>versioning</code> field is deliberately not carried forward.</p>',21)])])}const u=a(i,[["render",d]]);export{p as __pageData,u as default};
